window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ee8eaa0e505d94c3"]={"versions": [{"id": "FIG-ee8eaa0e505d94c3", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) gemäß AUTOSAR R4.1.3 Template Specification (<code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die Struktur und Abhängigkeiten der Metaklasse <code>BswInternalBehavior</code>. Im AUTOSAR-Gesamtsystem bildet sie das BSW-seitige Äquivalent zum <code>SwcInternalBehavior</code> von VFB-Software-Komponenten.</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung der inneren Implementierungsdetails eines BSW-Moduls (Basic Software) für den BSW-Scheduler (SchM / Teil der RTE). Das Modell definiert ausführbare Code-Entitäten (<code>BswModuleEntity</code>), deren Aktivierungsereignisse (<code>BswEvent</code>), Speichernutzung, Concurrency-Mechanismen (<code>ExclusiveArea</code>), Modus-Policies sowie Partitions- und Core-Zuordnungen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Vererbungshierarchie</p>\n<ul class=\"fig-list\">\n<li><code>InternalBehavior</code> (abstrakt, spezialisiert <code>AtpStructureElement</code>): Allgemeine Basisklasse für komponentenin- und modulinterne Verhaltensbeschreibungen.</li>\n<li><code>BswInternalBehavior</code> (spezialisiert <code>InternalBehavior</code>): Konkrete Ausprägung für Module der Basessoftware.</li>\n</ul>\n<p class=\"fig-p\">#### Geerbte Kompositionen von <code>InternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+exclusiveArea</code> [0..*]: Komposition von <code>ExclusiveArea</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation»</code>. Definiert kritische Bereiche zum Schutz vor nebenläufigem Zugriff.</li>\n<li><code>+exclusiveAreaNestingOrder</code> [0..*]: Komposition von <code>ExclusiveAreaNestingOrder</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert zulässige Schachtelungsreihenfolgen zur präventiven Vermeidung von Deadlocks.</li>\n<li><code>+staticMemory</code> [0..*]: Komposition von <code>VariableDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation»</code>. Modulglobale statische Variablen.</li>\n<li><code>+constantMemory</code> [0..*]: Komposition von <code>ParameterDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation»</code>. ROM-/Flash-Konstanten des Moduls.</li>\n</ul>\n<p class=\"fig-p\">#### Eigene Kompositionen & Assoziationen von <code>BswInternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+entity</code> [1..*]: Komposition von <code>BswModuleEntity</code> (abstrakt, spezialisiert <code>ExecutableEntity</code>), markiert mit <code>«atpVariation»</code>. Zwingend mindestens eine Instanz erforderlich. Repräsentiert ausführbaren C-Code (z. B. MainFunctions, Callbacks, Interrupt-Handler).</li>\n<li><code>+event</code> [0..*]: Komposition von <code>BswEvent</code> (abstrakt, spezialisiert <code>AbstractEvent</code>), markiert mit <code>«atpVariation»</code>. Ereignisse, die Entities aktivieren.</li>\n<li><strong>Assoziation:</strong> <code>BswEvent</code> referenziert über <code>+startsOnEvent [1]</code> genau eine <code>BswModuleEntity</code>.</li>\n<li><code>+perInstanceParameter</code> [0..*]: Komposition von <code>ParameterDataPrototype</code>, markiert mit <code>«atpVariation»</code>. Parameter für instanziierbare BSW-Module.</li>\n<li><code>+triggerDirectImplementation</code> [0..*]: Komposition von <code>BswTriggerDirectImplementation</code>, markiert mit <code>«atpVariation»</code>. Bildet direkte Trigger-Aufrufe ohne Event-Queuing ab.</li>\n<li><code>+modeSenderPolicy</code> [0..*]: Komposition von <code>BswModeSenderPolicy</code>, markiert mit <code>«atpVariation»</code>. Richtlinie für das Senden/Umschalten von BSW-Modi.</li>\n<li><code>+modeReceiverPolicy</code> [0..*]: Komposition von <code>BswModeReceiverPolicy</code>, markiert mit <code>«atpVariation»</code>. Richtlinie für die Reaktion auf externe/interne Moduswechsel.</li>\n<li><code>+serviceDependency</code> [0..*]: Komposition von <code>BswServiceDependency</code> (spezialisiert <code>ServiceDependency</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Formalisierte Abhängigkeiten zu Systemdiensten (z. B. NVRAM Manager, Dem, ComM).</li>\n<li><code>+receptionPolicy</code> [0..*]: Komposition von <code>BswDataReceptionPolicy</code>, markiert mit <code>«atpVariation»</code>. Spezifiziert Pufferung und Semantik beim Datenempfang im BSW.</li>\n<li><code>+internalTriggeringPoint</code> [0..*]: Komposition von <code>BswInternalTriggeringPoint</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation»</code>. Ermöglicht modulinterne asynchrone Aktivierungspfade zwischen Entities.</li>\n<li><code>+distinguishedPartition</code> [0..*]: Komposition von <code>BswDistinguishedPartition</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation»</code>. Logische Partitionierungszuordnung für Multicore-/OS-Anwendungen.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotyp-Semantik</p>\n<ul class=\"fig-list\">\n<li><code>«atpVariation»</code>: Variation Point des AUTOSAR Template Profile. Ermöglicht Variantenbildung zu definierten Bindungszeitpunkten (PreCompile, LinkTime, PostBuild).</li>\n<li><code>«atpSplitable»</code>: Erlaubt die Verteilung der ARXML-Beschreibungen über mehrere Teildateien im Integrationsprozess.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Ausführungspfade zur Laufzeit im BSW-Scheduler:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierungskette:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein <code>BswEvent</code> (z. B. <code>BswTimingEvent</code>, <code>BswDataReceivedEvent</code>, <code>BswModeSwitchEvent</code>) tritt ein.</li>\n<li>Der BSW-Scheduler wertet <code>startsOnEvent</code> aus und disponiert die verknüpfte <code>BswModuleEntity</code> (in der Regel eine <code>BswSchedulableEntity</code>, gemappt auf einen OS-Task).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modulinterne Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine Entity feuert einen <code>BswInternalTriggeringPoint</code>.</li>\n<li>Dies aktiviert asynchron oder synchron eine nachgelagerte <code>BswModuleEntity</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kritische Abschnitte (Locking):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Zugriff auf <code>staticMemory</code> betritt die Entity eine <code>ExclusiveArea</code>.</li>\n<li>Die Ausführung wird durch <code>ExclusiveAreaNestingOrder</code> validiert, um Sperrhierarchien einzuhalten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modusabhängige Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Moduswechsel werden über <code>BswModeReceiverPolicy</code> evaluiert; sie deaktivieren oder aktivieren selektiv die Zuordnung von <code>BswEvent</code> zu <code>BswModuleEntity</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Erstellung (Treiber- & Stack-Entwickler):</strong></li>\n<li>Jedes BSW-Modul benötigt zwingend ein <code>BswInternalBehavior</code> mit mindestens einer Entity (<code>entity [1..*]</code>). Fehlt die Definition für zyklische Funktionen (<code>&lt;Modul&gt;_MainFunction</code>), schlägt die SchM-Task-Zuordnung fehl.</li>\n<li><strong>SchM-Codegenerierung & API-Vertrag:</strong></li>\n<li>Jede modellierte <code>ExclusiveArea</code> generiert die APIs <code>SchM_Enter_&lt;Modul&gt;_&lt;Area&gt;()</code> und <code>SchM_Exit_&lt;Modul&gt;_&lt;Area&gt;()</code>. Die Implementierung (Interrupt-Sperre, OS-Resource, Spinlock) wird erst in der BSW-Scheduler-Konfiguration festgelegt.</li>\n<li><strong>Multicore- & Memory-Mapping:</strong></li>\n<li><code>BswDistinguishedPartition</code> erzwingt die Zuweisung von Entities an dedizierte OS-Applikationen / CPU-Kerne.</li>\n<li>Deklarationen in <code>staticMemory</code> und <code>constantMemory</code> steuern die Zuordnung zu Memory-Sections (<code>MemMap.h</code>-Abstraktion).</li>\n<li><strong>Variantenmanagement:</strong></li>\n<li>Wegen der breiten Verwendung von <code>«atpVariation»</code> müssen Post-Build- und Link-Time-Konfigurationen konsistent über SwcBswMapping und SchM aufgelöst werden; inkompatible Variantenkriterien führen zu unauflösbaren Symbolreferenzen im C-Build.</li>\n</ul>"}, {"id": "FIG-92f3493812820b2a", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) gemäß AUTOSAR R4.1.3 Template Specification (<code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die Struktur und Abhängigkeiten der Metaklasse <code>BswInternalBehavior</code>. Im AUTOSAR-Gesamtsystem bildet sie das BSW-seitige Äquivalent zum <code>SwcInternalBehavior</code> von VFB-Software-Komponenten.</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung der inneren Implementierungsdetails eines BSW-Moduls (Basic Software) für den BSW-Scheduler (SchM / Teil der RTE). Das Modell definiert ausführbare Code-Entitäten (<code>BswModuleEntity</code>), deren Aktivierungsereignisse (<code>BswEvent</code>), Speichernutzung, Concurrency-Mechanismen (<code>ExclusiveArea</code>), Modus-Policies sowie Partitions- und Core-Zuordnungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Vererbungshierarchie</p>\n<ul class=\"fig-list\">\n<li><code>InternalBehavior</code> (abstrakt, spezialisiert <code>AtpStructureElement</code>): Allgemeine Basisklasse für komponentenin- und modulinterne Verhaltensbeschreibungen.</li>\n<li><code>BswInternalBehavior</code> (spezialisiert <code>InternalBehavior</code>): Konkrete Ausprägung für Module der Basessoftware.</li>\n<li><code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>): Richtlinie für die Datenempfangsverarbeitung.</li>\n</ul>\n<p class=\"fig-p\">#### Geerbte Kompositionen von <code>InternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+exclusiveArea</code> [0..*]: Komposition von <code>ExclusiveArea</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Definiert kritische Bereiche zum Schutz vor nebenläufigem Zugriff.</li>\n<li><code>+exclusiveAreaNestingOrder</code> [0..*]: Komposition von <code>ExclusiveAreaNestingOrder</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert zulässige Schachtelungsreihenfolgen zur präventiven Vermeidung von Deadlocks.</li>\n<li><code>+staticMemory</code> [0..*]: Komposition von <code>VariableDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Modulglobale statische Variablen.</li>\n<li><code>+constantMemory</code> [0..*]: Komposition von <code>ParameterDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. ROM-/Flash-Konstanten des Moduls.</li>\n</ul>\n<p class=\"fig-p\">#### Eigene Kompositionen & Assoziationen von <code>BswInternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+entity</code> [1..*]: Komposition von <code>BswModuleEntity</code> (abstrakt, spezialisiert <code>ExecutableEntity</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Zwingend mindestens eine Instanz erforderlich. Repräsentiert ausführbaren C-Code (z. B. MainFunctions, Callbacks, Interrupt-Handler).</li>\n<li><code>+event</code> [0..*]: Komposition von <code>BswEvent</code> (abstrakt, spezialisiert <code>AbstractEvent</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ereignisse, die Entities aktivieren.</li>\n<li><strong>Assoziation:</strong> <code>BswEvent</code> referenziert über <code>+startsOnEvent [1]</code> genau eine <code>BswModuleEntity</code>.</li>\n<li><code>+perInstanceParameter</code> [0..*]: Komposition von <code>ParameterDataPrototype</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Parameter für instanziierbare BSW-Module.</li>\n<li><code>+triggerDirectImplementation</code> [0..*]: Komposition von <code>BswTriggerDirectImplementation</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Bildet direkte Trigger-Aufrufe ohne Event-Queuing ab.</li>\n<li><code>+modeSenderPolicy</code> [0..*]: Komposition von <code>BswModeSenderPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für das Senden/Umschalten von BSW-Modi.</li>\n<li><code>+modeReceiverPolicy</code> [0..*]: Komposition von <code>BswModeReceiverPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für die Reaktion auf externe/interne Moduswechsel.</li>\n<li><code>+serviceDependency</code> [0..*]: Komposition von <code>BswServiceDependency</code> (spezialisiert <code>ServiceDependency</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Formalisierte Abhängigkeiten zu Systemdiensten (z. B. NVRAM Manager, Dem, ComM).</li>\n<li><code>+receptionPolicy</code> [0..*]: Komposition von <code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert Pufferung und Semantik beim Datenempfang im BSW.</li>\n<li><code>+internalTriggeringPoint</code> [0..*]: Komposition von <code>BswInternalTriggeringPoint</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ermöglicht modulinterne asynchrone Aktivierungspfade zwischen Entities.</li>\n<li><code>+distinguishedPartition</code> [0..*]: Komposition von <code>BswDistinguishedPartition</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Logische Partitionierungszuordnung für Multicore-/OS-Anwendungen.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotyp-Semantik</p>\n<ul class=\"fig-list\">\n<li><code>«atpVariation»</code>: Variation Point des AUTOSAR Template Profile. Ermöglicht Variantenbildung zu definierten Bindungszeitpunkten (PreCompile, LinkTime, PostBuild).</li>\n<li><code>«atpSplitable»</code>: Erlaubt die Verteilung der ARXML-Beschreibungen über mehrere Teildateien im Integrationsprozess.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Ausführungspfade zur Laufzeit im BSW-Scheduler:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierungskette:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein <code>BswEvent</code> (z. B. <code>BswTimingEvent</code>, <code>BswDataReceivedEvent</code>, <code>BswModeSwitchEvent</code>) tritt ein.</li>\n<li>Der BSW-Scheduler wertet <code>startsOnEvent</code> aus und disponiert die verknüpfte <code>BswModuleEntity</code> (in der Regel eine <code>BswSchedulableEntity</code>, gemappt auf einen OS-Task).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modulinterne Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine Entity feuert einen <code>BswInternalTriggeringPoint</code>.</li>\n<li>Dies aktiviert asynchron oder synchron eine nachgelagerte <code>BswModuleEntity</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kritische Abschnitte (Locking):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Zugriff auf <code>staticMemory</code> betritt die Entity eine <code>ExclusiveArea</code>.</li>\n<li>Die Ausführung wird durch <code>ExclusiveAreaNestingOrder</code> validiert, um Sperrhierarchien einzuhalten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modusabhängige Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Moduswechsel werden über <code>BswModeReceiverPolicy</code> evaluiert; sie deaktivieren oder aktivieren selektiv die Zuordnung von <code>BswEvent</code> zu <code>BswModuleEntity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Erstellung (Treiber- & Stack-Entwickler):</strong></li>\n<li>Jedes BSW-Modul benötigt zwingend ein <code>BswInternalBehavior</code> mit mindestens einer Entity (<code>entity [1..*]</code>). Fehlt die Definition für zyklische Funktionen (<code>&lt;Modul&gt;_MainFunction</code>), schlägt die SchM-Task-Zuordnung fehl.</li>\n<li><strong>SchM-Codegenerierung & API-Vertrag:</strong></li>\n<li>Jede modellierte <code>ExclusiveArea</code> generiert die APIs <code>SchM_Enter_&lt;Modul&gt;_&lt;Area&gt;()</code> und <code>SchM_Exit_&lt;Modul&gt;_&lt;Area&gt;()</code>. Die Implementierung (Interrupt-Sperre, OS-Resource, Spinlock) wird erst in der BSW-Scheduler-Konfiguration festgelegt.</li>\n<li><strong>Multicore- & Memory-Mapping:</strong></li>\n<li><code>BswDistinguishedPartition</code> erzwingt die Zuweisung von Entities an dedizierte OS-Applikationen / CPU-Kerne.</li>\n<li>Deklarationen in <code>staticMemory</code> und <code>constantMemory</code> steuern die Zuordnung zu Memory-Sections (<code>MemMap.h</code>-Abstraktion).</li>\n<li><strong>Variantenmanagement:</strong></li>\n<li>Wegen der breiten Verwendung von <code>«atpVariation»</code> müssen Post-Build- und Link-Time-Konfigurationen konsistent über SwcBswMapping und SchM aufgelöst werden; inkompatible Variantenkriterien führen zu unauflösbaren Symbolreferenzen im C-Build.</li>\n</ul>"}, {"id": "FIG-058c5c9bbe1a9c12", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) gemäß AUTOSAR R4.1.3 Template Specification (<code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die Struktur und Abhängigkeiten der Metaklasse <code>BswInternalBehavior</code>. Im AUTOSAR-Gesamtsystem bildet sie das BSW-seitige Äquivalent zum <code>SwcInternalBehavior</code> von VFB-Software-Komponenten.</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung der inneren Implementierungsdetails eines BSW-Moduls (Basic Software) für den BSW-Scheduler (SchM / Teil der RTE). Das Modell definiert ausführbare Code-Entitäten (<code>BswModuleEntity</code>), deren Aktivierungsereignisse (<code>BswEvent</code>), Speichernutzung, Concurrency-Mechanismen (<code>ExclusiveArea</code>), Modus-Policies sowie Partitions- und Core-Zuordnungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Vererbungshierarchie</p>\n<ul class=\"fig-list\">\n<li><code>InternalBehavior</code> (abstrakt, spezialisiert <code>AtpStructureElement</code>): Allgemeine Basisklasse für komponentenin- und modulinterne Verhaltensbeschreibungen.</li>\n<li><code>BswInternalBehavior</code> (spezialisiert <code>InternalBehavior</code>): Konkrete Ausprägung für Module der Basessoftware.</li>\n<li><code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>): Richtlinie für die Datenempfangsverarbeitung.</li>\n</ul>\n<p class=\"fig-p\">#### Geerbte Kompositionen von <code>InternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+exclusiveArea</code> [0..*]: Komposition von <code>ExclusiveArea</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Definiert kritische Bereiche zum Schutz vor nebenläufigem Zugriff.</li>\n<li><code>+exclusiveAreaNestingOrder</code> [0..*]: Komposition von <code>ExclusiveAreaNestingOrder</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert zulässige Schachtelungsreihenfolgen zur präventiven Vermeidung von Deadlocks.</li>\n<li><code>+staticMemory</code> [0..*]: Komposition von <code>VariableDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Modulglobale statische Variablen.</li>\n<li><code>+constantMemory</code> [0..*]: Komposition von <code>ParameterDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. ROM-/Flash-Konstanten des Moduls.</li>\n</ul>\n<p class=\"fig-p\">#### Eigene Kompositionen & Assoziationen von <code>BswInternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+arTypedPerInstanceMemory</code> [0..*]: Komposition von <code>VariableDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Typisierter instanzspezifischer Speicher für BSW-Modulinstanzen.</li>\n<li><code>+entity</code> [0..*]: Komposition von <code>BswModuleEntity</code> (abstrakt, spezialisiert <code>ExecutableEntity</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Repräsentiert ausführbaren C-Code (z. B. MainFunctions, Callbacks, Interrupt-Handler).</li>\n<li><code>+event</code> [0..*]: Komposition von <code>BswEvent</code> (abstrakt, spezialisiert <code>AbstractEvent</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ereignisse, die Entities aktivieren.</li>\n<li><strong>Assoziation:</strong> <code>BswEvent</code> referenziert über <code>+startsOnEvent [1]</code> genau eine <code>BswModuleEntity</code>.</li>\n<li><code>+perInstanceParameter</code> [0..*]: Komposition von <code>ParameterDataPrototype</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Parameter für instanziierbare BSW-Module.</li>\n<li><code>+triggerDirectImplementation</code> [0..*]: Komposition von <code>BswTriggerDirectImplementation</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Bildet direkte Trigger-Aufrufe ohne Event-Queuing ab.</li>\n<li><code>+modeSenderPolicy</code> [0..*]: Komposition von <code>BswModeSenderPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für das Senden/Umschalten von BSW-Modi.</li>\n<li><code>+modeReceiverPolicy</code> [0..*]: Komposition von <code>BswModeReceiverPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für die Reaktion auf externe/interne Moduswechsel.</li>\n<li><code>+serviceDependency</code> [0..*]: Komposition von <code>BswServiceDependency</code> (spezialisiert <code>ServiceDependency</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Formalisierte Abhängigkeiten zu Systemdiensten (z. B. NVRAM Manager, Dem, ComM).</li>\n<li><code>+receptionPolicy</code> [0..*]: Komposition von <code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert Pufferung und Semantik beim Datenempfang im BSW.</li>\n<li><code>+internalTriggeringPoint</code> [0..*]: Komposition von <code>BswInternalTriggeringPoint</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ermöglicht modulinterne asynchrone Aktivierungspfade zwischen Entities.</li>\n<li><code>+distinguishedPartition</code> [0..*]: Komposition von <code>BswDistinguishedPartition</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Logische Partitionierungszuordnung für Multicore-/OS-Anwendungen.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotyp-Semantik</p>\n<ul class=\"fig-list\">\n<li><code>«atpVariation»</code>: Variation Point des AUTOSAR Template Profile. Ermöglicht Variantenbildung zu definierten Bindungszeitpunkten (PreCompile, LinkTime, PostBuild).</li>\n<li><code>«atpSplitable»</code>: Erlaubt die Verteilung der ARXML-Beschreibungen über mehrere Teildateien im Integrationsprozess.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Ausführungspfade zur Laufzeit im BSW-Scheduler:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierungskette:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein <code>BswEvent</code> (z. B. <code>BswTimingEvent</code>, <code>BswDataReceivedEvent</code>, <code>BswModeSwitchEvent</code>) tritt ein.</li>\n<li>Der BSW-Scheduler wertet <code>startsOnEvent</code> aus und disponiert die verknüpfte <code>BswModuleEntity</code> (in der Regel eine <code>BswSchedulableEntity</code>, gemappt auf einen OS-Task).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modulinterne Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine Entity feuert einen <code>BswInternalTriggeringPoint</code>.</li>\n<li>Dies aktiviert asynchron oder synchron eine nachgelagerte <code>BswModuleEntity</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kritische Abschnitte (Locking):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Zugriff auf <code>staticMemory</code> betritt die Entity eine <code>ExclusiveArea</code>.</li>\n<li>Die Ausführung wird durch <code>ExclusiveAreaNestingOrder</code> validiert, um Sperrhierarchien einzuhalten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modusabhängige Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Moduswechsel werden über <code>BswModeReceiverPolicy</code> evaluiert; sie deaktivieren oder aktivieren selektiv die Zuordnung von <code>BswEvent</code> zu <code>BswModuleEntity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Erstellung (Treiber- & Stack-Entwickler):</strong></li>\n<li><code>BswInternalBehavior</code> erlaubt optionale Entitäten (<code>entity [0..*]</code>). Für Module mit zyklischen Funktionen (<code>&lt;Modul&gt;_MainFunction</code>) oder Callbacks werden <code>BswModuleEntity</code>-Instanzen definiert, um die SchM-Task-Zuordnung zu ermöglichen.</li>\n<li><strong>SchM-Codegenerierung & API-Vertrag:</strong></li>\n<li>Jede modellierte <code>ExclusiveArea</code> generiert die APIs <code>SchM_Enter_&lt;Modul&gt;_&lt;Area&gt;()</code> und <code>SchM_Exit_&lt;Modul&gt;_&lt;Area&gt;()</code>. Die Implementierung (Interrupt-Sperre, OS-Resource, Spinlock) wird erst in der BSW-Scheduler-Konfiguration festgelegt.</li>\n<li><strong>Multicore- & Memory-Mapping:</strong></li>\n<li><code>BswDistinguishedPartition</code> erzwingt die Zuweisung von Entities an dedizierte OS-Applikationen / CPU-Kerne.</li>\n<li>Deklarationen in <code>staticMemory</code>, <code>constantMemory</code> und <code>arTypedPerInstanceMemory</code> steuern die Zuordnung zu Memory-Sections (<code>MemMap.h</code>-Abstraktion) und ermöglichen instanzspezifische Speicherbereiche.</li>\n<li><strong>Variantenmanagement:</strong></li>\n<li>Wegen der breiten Verwendung von <code>«atpVariation»</code> und <code>«atpSplitable»</code> müssen Post-Build- und Link-Time-Konfigurationen konsistent über SwcBswMapping und SchM aufgelöst werden; inkompatible Variantenkriterien führen zu unauflösbaren Symbolreferenzen im C-Build.</li>\n</ul>"}, {"id": "FIG-56a052af4bd8b83f", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) gemäß AUTOSAR R4.1.3 Template Specification (<code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die Struktur und Abhängigkeiten der Metaklasse <code>BswInternalBehavior</code>. Im AUTOSAR-Gesamtsystem bildet sie das BSW-seitige Äquivalent zum <code>SwcInternalBehavior</code> von VFB-Software-Komponenten.</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung der inneren Implementierungsdetails eines BSW-Moduls (Basic Software) für den BSW-Scheduler (SchM / Teil der RTE). Das Modell definiert ausführbare Code-Entitäten (<code>BswModuleEntity</code>), deren Aktivierungsereignisse (<code>BswEvent</code>), Speichernutzung, Concurrency-Mechanismen (<code>ExclusiveArea</code>), Modus-Policies sowie Partitions- und Core-Zuordnungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Vererbungshierarchie</p>\n<ul class=\"fig-list\">\n<li><code>InternalBehavior</code> (abstrakt, spezialisiert <code>AtpStructureElement</code>): Allgemeine Basisklasse für komponentenin- und modulinterne Verhaltensbeschreibungen.</li>\n<li><code>BswInternalBehavior</code> (spezialisiert <code>InternalBehavior</code>): Konkrete Ausprägung für Module der Basessoftware.</li>\n<li><code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>): Richtlinie für die Datenempfangsverarbeitung.</li>\n</ul>\n<p class=\"fig-p\">#### Geerbte Kompositionen von <code>InternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+exclusiveArea</code> [0..*]: Komposition von <code>ExclusiveArea</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Definiert kritische Bereiche zum Schutz vor nebenläufigem Zugriff.</li>\n<li><code>+exclusiveAreaNestingOrder</code> [0..*]: Komposition von <code>ExclusiveAreaNestingOrder</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert zulässige Schachtelungsreihenfolgen zur präventiven Vermeidung von Deadlocks.</li>\n<li><code>+staticMemory</code> [0..*]: Komposition von <code>VariableDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Modulglobale statische Variablen.</li>\n<li><code>+constantMemory</code> [0..*]: Komposition von <code>ParameterDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. ROM-/Flash-Konstanten des Moduls.</li>\n</ul>\n<p class=\"fig-p\">#### Eigene Kompositionen & Assoziationen von <code>BswInternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+arTypedPerInstanceMemory</code> [0..*]: Komposition von <code>VariableDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Typisierter instanzspezifischer Speicher für BSW-Modulinstanzen.</li>\n<li><code>+entity</code> [0..*]: Komposition von <code>BswModuleEntity</code> (abstrakt, spezialisiert <code>ExecutableEntity</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Repräsentiert ausführbaren C-Code (z. B. MainFunctions, Callbacks, Interrupt-Handler).</li>\n<li><code>+event</code> [0..*]: Komposition von <code>BswEvent</code> (abstrakt, spezialisiert <code>AbstractEvent</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ereignisse, die Entities aktivieren.</li>\n<li><strong>Assoziation:</strong> <code>BswEvent</code> referenziert über <code>+startsOnEvent [1]</code> genau eine <code>BswModuleEntity</code>.</li>\n<li><code>+perInstanceParameter</code> [0..*]: Komposition von <code>ParameterDataPrototype</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Parameter für instanziierbare BSW-Module.</li>\n<li><code>+triggerDirectImplementation</code> [0..*]: Komposition von <code>BswTriggerDirectImplementation</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Bildet direkte Trigger-Aufrufe ohne Event-Queuing ab.</li>\n<li><code>+modeSenderPolicy</code> [0..*]: Komposition von <code>BswModeSenderPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für das Senden/Umschalten von BSW-Modi.</li>\n<li><code>+modeReceiverPolicy</code> [0..*]: Komposition von <code>BswModeReceiverPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für die Reaktion auf externe/interne Moduswechsel.</li>\n<li><code>+serviceDependency</code> [0..*]: Komposition von <code>BswServiceDependency</code> (spezialisiert <code>ServiceDependency</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Formalisierte Abhängigkeiten zu Systemdiensten (z. B. NVRAM Manager, Dem, ComM).</li>\n<li><code>+receptionPolicy</code> [0..*]: Komposition von <code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert Pufferung und Semantik beim Datenempfang im BSW.</li>\n<li><code>+internalTriggeringPoint</code> [0..*]: Komposition von <code>BswInternalTriggeringPoint</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ermöglicht modulinterne asynchrone Aktivierungspfade zwischen Entities.</li>\n<li><code>+distinguishedPartition</code> [0..*]: Komposition von <code>BswDistinguishedPartition</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Logische Partitionierungszuordnung für Multicore-/OS-Anwendungen.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotyp-Semantik</p>\n<ul class=\"fig-list\">\n<li><code>«atpVariation»</code>: Variation Point des AUTOSAR Template Profile. Ermöglicht Variantenbildung zu definierten Bindungszeitpunkten (PreCompile, LinkTime, PostBuild).</li>\n<li><code>«atpSplitable»</code>: Erlaubt die Verteilung der ARXML-Beschreibungen über mehrere Teildateien im Integrationsprozess.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Ausführungspfade zur Laufzeit im BSW-Scheduler:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierungskette:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein <code>BswEvent</code> (z. B. <code>BswTimingEvent</code>, <code>BswDataReceivedEvent</code>, <code>BswModeSwitchEvent</code>) tritt ein.</li>\n<li>Der BSW-Scheduler wertet <code>startsOnEvent</code> aus und disponiert die verknüpfte <code>BswModuleEntity</code> (in der Regel eine <code>BswSchedulableEntity</code>, gemappt auf einen OS-Task).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modulinterne Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine Entity feuert einen <code>BswInternalTriggeringPoint</code>.</li>\n<li>Dies aktiviert asynchron oder synchron eine nachgelagerte <code>BswModuleEntity</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kritische Abschnitte (Locking):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Zugriff auf <code>staticMemory</code> betritt die Entity eine <code>ExclusiveArea</code>.</li>\n<li>Die Ausführung wird durch <code>ExclusiveAreaNestingOrder</code> validiert, um Sperrhierarchien einzuhalten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modusabhängige Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Moduswechsel werden über <code>BswModeReceiverPolicy</code> evaluiert; sie deaktivieren oder aktivieren selektiv die Zuordnung von <code>BswEvent</code> zu <code>BswModuleEntity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Erstellung (Treiber- & Stack-Entwickler):</strong></li>\n<li><code>BswInternalBehavior</code> erlaubt optionale Entitäten (<code>entity [0..*]</code>). Für Module mit zyklischen Funktionen (<code>&lt;Modul&gt;_MainFunction</code>) oder Callbacks werden <code>BswModuleEntity</code>-Instanzen definiert, um die SchM-Task-Zuordnung zu ermöglichen.</li>\n<li><strong>SchM-Codegenerierung & API-Vertrag:</strong></li>\n<li>Jede modellierte <code>ExclusiveArea</code> generiert die APIs <code>SchM_Enter_&lt;Modul&gt;_&lt;Area&gt;()</code> und <code>SchM_Exit_&lt;Modul&gt;_&lt;Area&gt;()</code>. Die Implementierung (Interrupt-Sperre, OS-Resource, Spinlock) wird erst in der BSW-Scheduler-Konfiguration festgelegt.</li>\n<li><strong>Multicore- & Memory-Mapping:</strong></li>\n<li><code>BswDistinguishedPartition</code> erzwingt die Zuweisung von Entities an dedizierte OS-Applikationen / CPU-Kerne.</li>\n<li>Deklarationen in <code>staticMemory</code>, <code>constantMemory</code> und <code>arTypedPerInstanceMemory</code> steuern die Zuordnung zu Memory-Sections (<code>MemMap.h</code>-Abstraktion) und ermöglichen instanzspezifische Speicherbereiche.</li>\n<li><strong>Variantenmanagement:</strong></li>\n<li>Wegen der breiten Verwendung von <code>«atpVariation»</code> und <code>«atpSplitable»</code> müssen Post-Build- und Link-Time-Konfigurationen konsistent über SwcBswMapping und SchM aufgelöst werden; inkompatible Variantenkriterien führen zu unauflösbaren Symbolreferenzen im C-Build.</li>\n</ul>"}, {"id": "FIG-4a0059011b56e100", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) gemäß AUTOSAR R4.1.3 Template Specification (<code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die Struktur und Abhängigkeiten der Metaklasse <code>BswInternalBehavior</code>. Im AUTOSAR-Gesamtsystem bildet sie das BSW-seitige Äquivalent zum <code>SwcInternalBehavior</code> von VFB-Software-Komponenten.</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung der inneren Implementierungsdetails eines BSW-Moduls (Basic Software) für den BSW-Scheduler (SchM / Teil der RTE). Das Modell definiert ausführbare Code-Entitäten (<code>BswModuleEntity</code>), deren Aktivierungsereignisse (<code>BswEvent</code>), Speichernutzung, Concurrency-Mechanismen (<code>ExclusiveArea</code>), Modus-Policies sowie Partitions- und Core-Zuordnungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Vererbungshierarchie</p>\n<ul class=\"fig-list\">\n<li><code>InternalBehavior</code> (abstrakt, spezialisiert <code>AtpStructureElement</code>): Allgemeine Basisklasse für komponentenin- und modulinterne Verhaltensbeschreibungen.</li>\n<li><code>BswInternalBehavior</code> (spezialisiert <code>InternalBehavior</code>): Konkrete Ausprägung für Module der Basessoftware.</li>\n<li><code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>): Richtlinie für die Datenempfangsverarbeitung.</li>\n</ul>\n<p class=\"fig-p\">#### Geerbte Kompositionen von <code>InternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+exclusiveArea</code> [0..*]: Komposition von <code>ExclusiveArea</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Definiert kritische Bereiche zum Schutz vor nebenläufigem Zugriff.</li>\n<li><code>+exclusiveAreaNestingOrder</code> [0..*]: Komposition von <code>ExclusiveAreaNestingOrder</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert zulässige Schachtelungsreihenfolgen zur präventiven Vermeidung von Deadlocks.</li>\n<li><code>+staticMemory</code> [0..*]: Komposition von <code>VariableDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Modulglobale statische Variablen.</li>\n<li><code>+constantMemory</code> [0..*]: Komposition von <code>ParameterDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. ROM-/Flash-Konstanten des Moduls.</li>\n</ul>\n<p class=\"fig-p\">#### Eigene Kompositionen & Assoziationen von <code>BswInternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+entity</code> [0..*]: Komposition von <code>BswModuleEntity</code> (abstrakt, spezialisiert <code>ExecutableEntity</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Repräsentiert ausführbaren C-Code (z. B. MainFunctions, Callbacks, Interrupt-Handler).</li>\n<li><code>+event</code> [0..*]: Komposition von <code>BswEvent</code> (abstrakt, spezialisiert <code>AbstractEvent</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ereignisse, die Entities aktivieren.</li>\n<li><strong>Assoziation:</strong> <code>BswEvent</code> referenziert über <code>+startsOnEvent [1]</code> genau eine <code>BswModuleEntity</code>.</li>\n<li><code>+perInstanceParameter</code> [0..*]: Komposition von <code>ParameterDataPrototype</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Parameter für instanziierbare BSW-Module.</li>\n<li><code>+triggerDirectImplementation</code> [0..*]: Komposition von <code>BswTriggerDirectImplementation</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Bildet direkte Trigger-Aufrufe ohne Event-Queuing ab.</li>\n<li><code>+modeSenderPolicy</code> [0..*]: Komposition von <code>BswModeSenderPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für das Senden/Umschalten von BSW-Modi.</li>\n<li><code>+modeReceiverPolicy</code> [0..*]: Komposition von <code>BswModeReceiverPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für die Reaktion auf externe/interne Moduswechsel.</li>\n<li><code>+serviceDependency</code> [0..*]: Komposition von <code>BswServiceDependency</code> (spezialisiert <code>ServiceDependency</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Formalisierte Abhängigkeiten zu Systemdiensten (z. B. NVRAM Manager, Dem, ComM).</li>\n<li><code>+receptionPolicy</code> [0..*]: Komposition von <code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert Pufferung und Semantik beim Datenempfang im BSW.</li>\n<li><code>+internalTriggeringPoint</code> [0..*]: Komposition von <code>BswInternalTriggeringPoint</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ermöglicht modulinterne asynchrone Aktivierungspfade zwischen Entities.</li>\n<li><code>+distinguishedPartition</code> [0..*]: Komposition von <code>BswDistinguishedPartition</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Logische Partitionierungszuordnung für Multicore-/OS-Anwendungen.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotyp-Semantik</p>\n<ul class=\"fig-list\">\n<li><code>«atpVariation»</code>: Variation Point des AUTOSAR Template Profile. Ermöglicht Variantenbildung zu definierten Bindungszeitpunkten (PreCompile, LinkTime, PostBuild).</li>\n<li><code>«atpSplitable»</code>: Erlaubt die Verteilung der ARXML-Beschreibungen über mehrere Teildateien im Integrationsprozess.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Ausführungspfade zur Laufzeit im BSW-Scheduler:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierungskette:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein <code>BswEvent</code> (z. B. <code>BswTimingEvent</code>, <code>BswDataReceivedEvent</code>, <code>BswModeSwitchEvent</code>) tritt ein.</li>\n<li>Der BSW-Scheduler wertet <code>startsOnEvent</code> aus und disponiert die verknüpfte <code>BswModuleEntity</code> (in der Regel eine <code>BswSchedulableEntity</code>, gemappt auf einen OS-Task).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modulinterne Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine Entity feuert einen <code>BswInternalTriggeringPoint</code>.</li>\n<li>Dies aktiviert asynchron oder synchron eine nachgelagerte <code>BswModuleEntity</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kritische Abschnitte (Locking):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Zugriff auf <code>staticMemory</code> betritt die Entity eine <code>ExclusiveArea</code>.</li>\n<li>Die Ausführung wird durch <code>ExclusiveAreaNestingOrder</code> validiert, um Sperrhierarchien einzuhalten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modusabhängige Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Moduswechsel werden über <code>BswModeReceiverPolicy</code> evaluiert; sie deaktivieren oder aktivieren selektiv die Zuordnung von <code>BswEvent</code> zu <code>BswModuleEntity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Erstellung (Treiber- & Stack-Entwickler):</strong></li>\n<li><code>BswInternalBehavior</code> erlaubt optionale Entitäten (<code>entity [0..*]</code>). Für Module mit zyklischen Funktionen (<code>&lt;Modul&gt;_MainFunction</code>) oder Callbacks werden <code>BswModuleEntity</code>-Instanzen definiert, um die SchM-Task-Zuordnung zu ermöglichen.</li>\n<li><strong>SchM-Codegenerierung & API-Vertrag:</strong></li>\n<li>Jede modellierte <code>ExclusiveArea</code> generiert die APIs <code>SchM_Enter_&lt;Modul&gt;_&lt;Area&gt;()</code> und <code>SchM_Exit_&lt;Modul&gt;_&lt;Area&gt;()</code>. Die Implementierung (Interrupt-Sperre, OS-Resource, Spinlock) wird erst in der BSW-Scheduler-Konfiguration festgelegt.</li>\n<li><strong>Multicore- & Memory-Mapping:</strong></li>\n<li><code>BswDistinguishedPartition</code> erzwingt die Zuweisung von Entities an dedizierte OS-Applikationen / CPU-Kerne.</li>\n<li>Deklarationen in <code>staticMemory</code> und <code>constantMemory</code> steuern die Zuordnung zu Memory-Sections (<code>MemMap.h</code>-Abstraktion).</li>\n<li><strong>Variantenmanagement:</strong></li>\n<li>Wegen der breiten Verwendung von <code>«atpVariation»</code> und <code>«atpSplitable»</code> müssen Post-Build- und Link-Time-Konfigurationen konsistent über SwcBswMapping und SchM aufgelöst werden; inkompatible Variantenkriterien führen zu unauflösbaren Symbolreferenzen im C-Build.</li>\n</ul>"}, {"id": "FIG-f3a8bc6e4e85bc52", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) gemäß AUTOSAR R4.1.3 Template Specification (<code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die Struktur und Abhängigkeiten der Metaklasse <code>BswInternalBehavior</code>. Im AUTOSAR-Gesamtsystem bildet sie das BSW-seitige Äquivalent zum <code>SwcInternalBehavior</code> von VFB-Software-Komponenten.</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung der inneren Implementierungsdetails eines BSW-Moduls (Basic Software) für den BSW-Scheduler (SchM / Teil der RTE). Das Modell definiert ausführbare Code-Entitäten (<code>BswModuleEntity</code>), deren Aktivierungsereignisse (<code>BswEvent</code>), Speichernutzung, Concurrency-Mechanismen (<code>ExclusiveArea</code>), Modus-Policies sowie Partitions- und Core-Zuordnungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Vererbungshierarchie</p>\n<ul class=\"fig-list\">\n<li><code>InternalBehavior</code> (abstrakt, spezialisiert <code>AtpStructureElement</code>): Allgemeine Basisklasse für komponentenin- und modulinterne Verhaltensbeschreibungen.</li>\n<li><code>BswInternalBehavior</code> (spezialisiert <code>InternalBehavior</code>): Konkrete Ausprägung für Module der Basessoftware.</li>\n<li><code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>): Richtlinie für die Datenempfangsverarbeitung.</li>\n</ul>\n<p class=\"fig-p\">#### Geerbte Kompositionen von <code>InternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+exclusiveArea</code> [0..*]: Komposition von <code>ExclusiveArea</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Definiert kritische Bereiche zum Schutz vor nebenläufigem Zugriff.</li>\n<li><code>+exclusiveAreaNestingOrder</code> [0..*]: Komposition von <code>ExclusiveAreaNestingOrder</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert zulässige Schachtelungsreihenfolgen zur präventiven Vermeidung von Deadlocks.</li>\n<li><code>+staticMemory</code> [0..*]: Komposition von <code>VariableDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Modulglobale statische Variablen.</li>\n<li><code>+constantMemory</code> [0..*]: Komposition von <code>ParameterDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. ROM-/Flash-Konstanten des Moduls.</li>\n</ul>\n<p class=\"fig-p\">#### Eigene Kompositionen & Assoziationen von <code>BswInternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+entity</code> [0..*]: Komposition von <code>BswModuleEntity</code> (abstrakt, spezialisiert <code>ExecutableEntity</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Repräsentiert ausführbaren C-Code (z. B. MainFunctions, Callbacks, Interrupt-Handler).</li>\n<li><code>+event</code> [0..*]: Komposition von <code>BswEvent</code> (abstrakt, spezialisiert <code>AbstractEvent</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ereignisse, die Entities aktivieren.</li>\n<li><strong>Assoziation:</strong> <code>BswEvent</code> referenziert über <code>+startsOnEvent [0..1]</code> maximal eine <code>BswModuleEntity</code>.</li>\n<li><code>+perInstanceParameter</code> [0..*]: Komposition von <code>ParameterDataPrototype</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Parameter für instanziierbare BSW-Module.</li>\n<li><code>+triggerDirectImplementation</code> [0..*]: Komposition von <code>BswTriggerDirectImplementation</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Bildet direkte Trigger-Aufrufe ohne Event-Queuing ab.</li>\n<li><code>+modeSenderPolicy</code> [0..*]: Komposition von <code>BswModeSenderPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für das Senden/Umschalten von BSW-Modi.</li>\n<li><code>+modeReceiverPolicy</code> [0..*]: Komposition von <code>BswModeReceiverPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für die Reaktion auf externe/interne Moduswechsel.</li>\n<li><code>+serviceDependency</code> [0..*]: Komposition von <code>BswServiceDependency</code> (spezialisiert <code>ServiceDependency</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Formalisierte Abhängigkeiten zu Systemdiensten (z. B. NVRAM Manager, Dem, ComM).</li>\n<li><code>+receptionPolicy</code> [0..*]: Komposition von <code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert Pufferung und Semantik beim Datenempfang im BSW.</li>\n<li><code>+internalTriggeringPoint</code> [0..*]: Komposition von <code>BswInternalTriggeringPoint</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ermöglicht modulinterne asynchrone Aktivierungspfade zwischen Entities.</li>\n<li><code>+distinguishedPartition</code> [0..*]: Komposition von <code>BswDistinguishedPartition</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Logische Partitionierungszuordnung für Multicore-/OS-Anwendungen.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotyp-Semantik</p>\n<ul class=\"fig-list\">\n<li><code>«atpVariation»</code>: Variation Point des AUTOSAR Template Profile. Ermöglicht Variantenbildung zu definierten Bindungszeitpunkten (PreCompile, LinkTime, PostBuild).</li>\n<li><code>«atpSplitable»</code>: Erlaubt die Verteilung der ARXML-Beschreibungen über mehrere Teildateien im Integrationsprozess.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Ausführungspfade zur Laufzeit im BSW-Scheduler:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierungskette:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein <code>BswEvent</code> (z. B. <code>BswTimingEvent</code>, <code>BswDataReceivedEvent</code>, <code>BswModeSwitchEvent</code>) tritt ein.</li>\n<li>Der BSW-Scheduler wertet <code>startsOnEvent</code> aus und disponiert die verknüpfte <code>BswModuleEntity</code> (in der Regel eine <code>BswSchedulableEntity</code>, gemappt auf einen OS-Task).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modulinterne Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine Entity feuert einen <code>BswInternalTriggeringPoint</code>.</li>\n<li>Dies aktiviert asynchron oder synchron eine nachgelagerte <code>BswModuleEntity</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kritische Abschnitte (Locking):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Zugriff auf <code>staticMemory</code> betritt die Entity eine <code>ExclusiveArea</code>.</li>\n<li>Die Ausführung wird durch <code>ExclusiveAreaNestingOrder</code> validiert, um Sperrhierarchien einzuhalten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modusabhängige Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Moduswechsel werden über <code>BswModeReceiverPolicy</code> evaluiert; sie deaktivieren oder aktivieren selektiv die Zuordnung von <code>BswEvent</code> zu <code>BswModuleEntity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Erstellung (Treiber- & Stack-Entwickler):</strong></li>\n<li><code>BswInternalBehavior</code> erlaubt optionale Entitäten (<code>entity [0..*]</code>). Für Module mit zyklischen Funktionen (<code>&lt;Modul&gt;_MainFunction</code>) oder Callbacks werden <code>BswModuleEntity</code>-Instanzen definiert, um die SchM-Task-Zuordnung zu ermöglichen.</li>\n<li><strong>SchM-Codegenerierung & API-Vertrag:</strong></li>\n<li>Jede modellierte <code>ExclusiveArea</code> generiert die APIs <code>SchM_Enter_&lt;Modul&gt;_&lt;Area&gt;()</code> und <code>SchM_Exit_&lt;Modul&gt;_&lt;Area&gt;()</code>. Die Implementierung (Interrupt-Sperre, OS-Resource, Spinlock) wird erst in der BSW-Scheduler-Konfiguration festgelegt.</li>\n<li><strong>Multicore- & Memory-Mapping:</strong></li>\n<li><code>BswDistinguishedPartition</code> erzwingt die Zuweisung von Entities an dedizierte OS-Applikationen / CPU-Kerne.</li>\n<li>Deklarationen in <code>staticMemory</code> und <code>constantMemory</code> steuern die Zuordnung zu Memory-Sections (<code>MemMap.h</code>-Abstraktion).</li>\n<li><strong>Variantenmanagement:</strong></li>\n<li>Wegen der breiten Verwendung von <code>«atpVariation»</code> und <code>«atpSplitable»</code> müssen Post-Build- und Link-Time-Konfigurationen konsistent über SwcBswMapping und SchM aufgelöst werden; inkompatible Variantenkriterien führen zu unauflösbaren Symbolreferenzen im C-Build.</li>\n</ul>"}, {"id": "FIG-8cf8219b80bfc11d", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) gemäß AUTOSAR R4.1.3 Template Specification (<code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die Struktur und Abhängigkeiten der Metaklasse <code>BswInternalBehavior</code>. Im AUTOSAR-Gesamtsystem bildet sie das BSW-seitige Äquivalent zum <code>SwcInternalBehavior</code> von VFB-Software-Komponenten.</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung der inneren Implementierungsdetails eines BSW-Moduls (Basic Software) für den BSW-Scheduler (SchM / Teil der RTE). Das Modell definiert ausführbare Code-Entitäten (<code>BswModuleEntity</code>), deren Aktivierungsereignisse (<code>BswEvent</code>), Speichernutzung, Concurrency-Mechanismen (<code>ExclusiveArea</code>), Modus-Policies sowie Partitions- und Core-Zuordnungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Vererbungshierarchie</p>\n<ul class=\"fig-list\">\n<li><code>InternalBehavior</code> (abstrakt, spezialisiert <code>AtpStructureElement</code>): Allgemeine Basisklasse für komponentenin- und modulinterne Verhaltensbeschreibungen.</li>\n<li><code>BswInternalBehavior</code> (spezialisiert <code>InternalBehavior</code>): Konkrete Ausprägung für Module der Basessoftware.</li>\n<li><code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>): Richtlinie für die Datenempfangsverarbeitung.</li>\n</ul>\n<p class=\"fig-p\">#### Geerbte Kompositionen von <code>InternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+exclusiveArea</code> [0..*]: Komposition von <code>ExclusiveArea</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Definiert kritische Bereiche zum Schutz vor nebenläufigem Zugriff.</li>\n<li><code>+exclusiveAreaNestingOrder</code> [0..*]: Komposition von <code>ExclusiveAreaNestingOrder</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert zulässige Schachtelungsreihenfolgen zur präventiven Vermeidung von Deadlocks.</li>\n<li><code>+staticMemory</code> [0..*]: Komposition von <code>VariableDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Modulglobale statische Variablen.</li>\n<li><code>+constantMemory</code> [0..*]: Komposition von <code>ParameterDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. ROM-/Flash-Konstanten des Moduls.</li>\n</ul>\n<p class=\"fig-p\">#### Eigene Kompositionen & Assoziationen von <code>BswInternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+entity</code> [0..*]: Komposition von <code>BswModuleEntity</code> (abstrakt, spezialisiert <code>ExecutableEntity</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Repräsentiert ausführbaren C-Code (z. B. MainFunctions, Callbacks, Interrupt-Handler).</li>\n<li><code>+event</code> [0..*]: Komposition von <code>BswEvent</code> (abstrakt, spezialisiert <code>AbstractEvent</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ereignisse, die Entities aktivieren.</li>\n<li><strong>Assoziation:</strong> <code>BswEvent</code> referenziert über <code>+startsOnEvent [0..1]</code> maximal eine <code>BswModuleEntity</code>.</li>\n<li><code>+perInstanceParameter</code> [0..*]: Komposition von <code>ParameterDataPrototype</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Parameter für instanziierbare BSW-Module.</li>\n<li><code>+triggerDirectImplementation</code> [0..*]: Komposition von <code>BswTriggerDirectImplementation</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Bildet direkte Trigger-Aufrufe ohne Event-Queuing ab.</li>\n<li><code>+modeSenderPolicy</code> [0..*]: Komposition von <code>BswModeSenderPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für das Senden/Umschalten von BSW-Modi.</li>\n<li><code>+modeReceiverPolicy</code> [0..*]: Komposition von <code>BswModeReceiverPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für die Reaktion auf externe/interne Moduswechsel.</li>\n<li><code>+serviceDependency</code> [0..*]: Komposition von <code>BswServiceDependency</code> (spezialisiert <code>ServiceDependency</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Formalisierte Abhängigkeiten zu Systemdiensten (z. B. NVRAM Manager, Dem, ComM).</li>\n<li><code>+receptionPolicy</code> [0..*]: Komposition von <code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert Pufferung und Semantik beim Datenempfang im BSW.</li>\n<li><code>+internalTriggeringPoint</code> [0..*]: Komposition von <code>BswInternalTriggeringPoint</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ermöglicht modulinterne asynchrone Aktivierungspfade zwischen Entities.</li>\n<li><code>+distinguishedPartition</code> [0..*]: Komposition von <code>BswDistinguishedPartition</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Logische Partitionierungszuordnung für Multicore-/OS-Anwendungen.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotyp-Semantik</p>\n<ul class=\"fig-list\">\n<li><code>«atpVariation»</code>: Variation Point des AUTOSAR Template Profile. Ermöglicht Variantenbildung zu definierten Bindungszeitpunkten (PreCompile, LinkTime, PostBuild).</li>\n<li><code>«atpSplitable»</code>: Erlaubt die Verteilung der ARXML-Beschreibungen über mehrere Teildateien im Integrationsprozess.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Ausführungspfade zur Laufzeit im BSW-Scheduler:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierungskette:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein <code>BswEvent</code> (z. B. <code>BswTimingEvent</code>, <code>BswDataReceivedEvent</code>, <code>BswModeSwitchEvent</code>) tritt ein.</li>\n<li>Der BSW-Scheduler wertet <code>startsOnEvent</code> aus und disponiert die verknüpfte <code>BswModuleEntity</code> (in der Regel eine <code>BswSchedulableEntity</code>, gemappt auf einen OS-Task).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modulinterne Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine Entity feuert einen <code>BswInternalTriggeringPoint</code>.</li>\n<li>Dies aktiviert asynchron oder synchron eine nachgelagerte <code>BswModuleEntity</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kritische Abschnitte (Locking):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Zugriff auf <code>staticMemory</code> betritt die Entity eine <code>ExclusiveArea</code>.</li>\n<li>Die Ausführung wird durch <code>ExclusiveAreaNestingOrder</code> validiert, um Sperrhierarchien einzuhalten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modusabhängige Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Moduswechsel werden über <code>BswModeReceiverPolicy</code> evaluiert; sie deaktivieren oder aktivieren selektiv die Zuordnung von <code>BswEvent</code> zu <code>BswModuleEntity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Erstellung (Treiber- & Stack-Entwickler):</strong></li>\n<li><code>BswInternalBehavior</code> erlaubt optionale Entitäten (<code>entity [0..*]</code>). Für Module mit zyklischen Funktionen (<code>&lt;Modul&gt;_MainFunction</code>) oder Callbacks werden <code>BswModuleEntity</code>-Instanzen definiert, um die SchM-Task-Zuordnung zu ermöglichen.</li>\n<li><strong>SchM-Codegenerierung & API-Vertrag:</strong></li>\n<li>Jede modellierte <code>ExclusiveArea</code> generiert die APIs <code>SchM_Enter_&lt;Modul&gt;_&lt;Area&gt;()</code> und <code>SchM_Exit_&lt;Modul&gt;_&lt;Area&gt;()</code>. Die Implementierung (Interrupt-Sperre, OS-Resource, Spinlock) wird erst in der BSW-Scheduler-Konfiguration festgelegt.</li>\n<li><strong>Multicore- & Memory-Mapping:</strong></li>\n<li><code>BswDistinguishedPartition</code> erzwingt die Zuweisung von Entities an dedizierte OS-Applikationen / CPU-Kerne.</li>\n<li>Deklarationen in <code>staticMemory</code> und <code>constantMemory</code> steuern die Zuordnung zu Memory-Sections (<code>MemMap.h</code>-Abstraktion).</li>\n<li><strong>Variantenmanagement:</strong></li>\n<li>Wegen der breiten Verwendung von <code>«atpVariation»</code> und <code>«atpSplitable»</code> müssen Post-Build- und Link-Time-Konfigurationen konsistent über SwcBswMapping und SchM aufgelöst werden; inkompatible Variantenkriterien führen zu unauflösbaren Symbolreferenzen im C-Build.</li>\n</ul>"}, {"id": "FIG-15b86a8921df3d3c", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) gemäß AUTOSAR R4.1.3 Template Specification (<code>AUTOSAR_TPS_BSWModuleDescriptionTemplate</code>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die Struktur und Abhängigkeiten der Metaklasse <code>BswInternalBehavior</code>. Im AUTOSAR-Gesamtsystem bildet sie das BSW-seitige Äquivalent zum <code>SwcInternalBehavior</code> von VFB-Software-Komponenten.</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung der inneren Implementierungsdetails eines BSW-Moduls (Basic Software) für den BSW-Scheduler (SchM / Teil der RTE). Das Modell definiert ausführbare Code-Entitäten (<code>BswModuleEntity</code>), deren Aktivierungsereignisse (<code>BswEvent</code>), Speichernutzung, Concurrency-Mechanismen (<code>ExclusiveArea</code>), Modus-Policies sowie Partitions- und Core-Zuordnungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Vererbungshierarchie</p>\n<ul class=\"fig-list\">\n<li><code>InternalBehavior</code> (abstrakt, spezialisiert <code>AtpStructureElement</code>): Allgemeine Basisklasse für komponentenin- und modulinterne Verhaltensbeschreibungen.</li>\n<li><code>BswInternalBehavior</code> (spezialisiert <code>InternalBehavior</code>): Konkrete Ausprägung für Module der Basessoftware.</li>\n<li><code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>): Richtlinie für die Datenempfangsverarbeitung.</li>\n</ul>\n<p class=\"fig-p\">#### Geerbte Kompositionen von <code>InternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+exclusiveArea</code> [0..*]: Komposition von <code>ExclusiveArea</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Definiert kritische Bereiche zum Schutz vor nebenläufigem Zugriff.</li>\n<li><code>+exclusiveAreaNestingOrder</code> [0..*]: Komposition von <code>ExclusiveAreaNestingOrder</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert zulässige Schachtelungsreihenfolgen zur präventiven Vermeidung von Deadlocks.</li>\n<li><code>+staticMemory</code> [0..*]: Komposition von <code>VariableDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Modulglobale statische Variablen.</li>\n<li><code>+constantMemory</code> [0..*]: Komposition von <code>ParameterDataPrototype</code> (erbt von <code>AutosarDataPrototype</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. ROM-/Flash-Konstanten des Moduls.</li>\n</ul>\n<p class=\"fig-p\">#### Eigene Kompositionen & Assoziationen von <code>BswInternalBehavior</code></p>\n<ul class=\"fig-list\">\n<li><code>+entity</code> [0..*]: Komposition von <code>BswModuleEntity</code> (abstrakt, spezialisiert <code>ExecutableEntity</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Repräsentiert ausführbaren C-Code (z. B. MainFunctions, Callbacks, Interrupt-Handler).</li>\n<li><code>+event</code> [0..*]: Komposition von <code>BswEvent</code> (abstrakt, spezialisiert <code>AbstractEvent</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ereignisse, die Entities aktivieren.</li>\n<li><strong>Assoziation:</strong> <code>BswEvent</code> referenziert über <code>+startsOnEvent [0..1]</code> maximal eine <code>BswModuleEntity</code>.</li>\n<li><code>+perInstanceParameter</code> [0..*]: Komposition von <code>ParameterDataPrototype</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Parameter für instanziierbare BSW-Module.</li>\n<li><code>+triggerDirectImplementation</code> [0..*]: Komposition von <code>BswTriggerDirectImplementation</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Bildet direkte Trigger-Aufrufe ohne Event-Queuing ab.</li>\n<li><code>+modeSenderPolicy</code> [0..*]: Komposition von <code>BswModeSenderPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für das Senden/Umschalten von BSW-Modi.</li>\n<li><code>+modeReceiverPolicy</code> [0..*]: Komposition von <code>BswModeReceiverPolicy</code>, markiert mit <code>«atpVariation, atpSplitable»</code>. Richtlinie für die Reaktion auf externe/interne Moduswechsel.</li>\n<li><code>+serviceDependency</code> [0..*]: Komposition von <code>BswServiceDependency</code> (spezialisiert <code>ServiceDependency</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Formalisierte Abhängigkeiten zu Systemdiensten (z. B. NVRAM Manager, Dem, ComM).</li>\n<li><code>+receptionPolicy</code> [0..*]: Komposition von <code>BswDataReceptionPolicy</code> (spezialisiert <code>BswApiOptions</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Spezifiziert Pufferung und Semantik beim Datenempfang im BSW.</li>\n<li><code>+internalTriggeringPoint</code> [0..*]: Komposition von <code>BswInternalTriggeringPoint</code> (erbt von <code>Identifiable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Ermöglicht modulinterne asynchrone Aktivierungspfade zwischen Entities.</li>\n<li><code>+distinguishedPartition</code> [0..*]: Komposition von <code>BswDistinguishedPartition</code> (erbt von <code>Referrable</code>), markiert mit <code>«atpVariation, atpSplitable»</code>. Logische Partitionierungszuordnung für Multicore-/OS-Anwendungen.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotyp-Semantik</p>\n<ul class=\"fig-list\">\n<li><code>«atpVariation»</code>: Variation Point des AUTOSAR Template Profile. Ermöglicht Variantenbildung zu definierten Bindungszeitpunkten (PreCompile, LinkTime, PostBuild).</li>\n<li><code>«atpSplitable»</code>: Erlaubt die Verteilung der ARXML-Beschreibungen über mehrere Teildateien im Integrationsprozess.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Metamodell definiert die Ausführungspfade zur Laufzeit im BSW-Scheduler:</p>\n<ol class=\"fig-list\">\n<li><strong>Aktivierungskette:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein <code>BswEvent</code> (z. B. <code>BswTimingEvent</code>, <code>BswDataReceivedEvent</code>, <code>BswModeSwitchEvent</code>) tritt ein.</li>\n<li>Der BSW-Scheduler wertet <code>startsOnEvent</code> aus und disponiert die verknüpfte <code>BswModuleEntity</code> (in der Regel eine <code>BswSchedulableEntity</code>, gemappt auf einen OS-Task).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modulinterne Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine Entity feuert einen <code>BswInternalTriggeringPoint</code>.</li>\n<li>Dies aktiviert asynchron oder synchron eine nachgelagerte <code>BswModuleEntity</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kritische Abschnitte (Locking):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Zugriff auf <code>staticMemory</code> betritt die Entity eine <code>ExclusiveArea</code>.</li>\n<li>Die Ausführung wird durch <code>ExclusiveAreaNestingOrder</code> validiert, um Sperrhierarchien einzuhalten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modusabhängige Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Moduswechsel werden über <code>BswModeReceiverPolicy</code> evaluiert; sie deaktivieren oder aktivieren selektiv die Zuordnung von <code>BswEvent</code> zu <code>BswModuleEntity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Erstellung (Treiber- & Stack-Entwickler):</strong></li>\n<li><code>BswInternalBehavior</code> erlaubt optionale Entitäten (<code>entity [0..*]</code>). Für Module mit zyklischen Funktionen (<code>&lt;Modul&gt;_MainFunction</code>) oder Callbacks werden <code>BswModuleEntity</code>-Instanzen definiert, um die SchM-Task-Zuordnung zu ermöglichen.</li>\n<li><strong>SchM-Codegenerierung & API-Vertrag:</strong></li>\n<li>Jede modellierte <code>ExclusiveArea</code> generiert die APIs <code>SchM_Enter_&lt;Modul&gt;_&lt;Area&gt;()</code> und <code>SchM_Exit_&lt;Modul&gt;_&lt;Area&gt;()</code>. Die Implementierung (Interrupt-Sperre, OS-Resource, Spinlock) wird erst in der BSW-Scheduler-Konfiguration festgelegt.</li>\n<li><strong>Multicore- & Memory-Mapping:</strong></li>\n<li><code>BswDistinguishedPartition</code> erzwingt die Zuweisung von Entities an dedizierte OS-Applikationen / CPU-Kerne.</li>\n<li>Deklarationen in <code>staticMemory</code> und <code>constantMemory</code> steuern die Zuordnung zu Memory-Sections (<code>MemMap.h</code>-Abstraktion).</li>\n<li><strong>Variantenmanagement:</strong></li>\n<li>Wegen der breiten Verwendung von <code>«atpVariation»</code> und <code>«atpSplitable»</code> müssen Post-Build- und Link-Time-Konfigurationen konsistent über SwcBswMapping und SchM aufgelöst werden; inkompatible Variantenkriterien führen zu unauflösbaren Symbolreferenzen im C-Build.</li>\n</ul>"}], "trans": [{"from": "FIG-ee8eaa0e505d94c3", "to": "FIG-92f3493812820b2a", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Generalisierung hinzugefügt: <code>BswDataReceptionPolicy</code> spezialisiert <code>BswApiOptions</code>.</li>\n<li>Stereotypisierung <code>«atpSplitable»</code> ergänzt für die Kompositionen <code>exclusiveArea</code>, <code>staticMemory</code>, <code>constantMemory</code> von <code>InternalBehavior</code> (nun jeweils <code>«atpVariation, atpSplitable»</code>).</li>\n<li>Stereotypisierung <code>«atpSplitable»</code> ergänzt für die Kompositionen <code>perInstanceParameter</code>, <code>entity</code>, <code>event</code>, <code>triggerDirectImplementation</code>, <code>modeSenderPolicy</code>, <code>modeReceiverPolicy</code>, <code>receptionPolicy</code>, <code>internalTriggeringPoint</code> und <code>distinguishedPartition</code> von <code>BswInternalBehavior</code> (nun jeweils <code>«atpVariation, atpSplitable»</code>).</li>\n</ul>"}, {"from": "FIG-92f3493812820b2a", "to": "FIG-058c5c9bbe1a9c12", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kardinalität der Komposition <code>+entity</code> (<code>BswInternalBehavior</code> -> <code>BswModuleEntity</code>) von <code>1..<em></code> auf <code>0..</em></code> gelockert.</li>\n<li>Neue Komposition <code>+arTypedPerInstanceMemory</code> [0..*] von <code>BswInternalBehavior</code> zu <code>VariableDataPrototype</code> mit Stereotyp <code>«atpVariation, atpSplitable»</code> hinzugefügt.</li>\n<li>Assoziation <code>+startsOnEvent</code> zwischen <code>BswEvent</code> und <code>BswModuleEntity</code> grafisch vertikal ausgerichtet.</li>\n</ul>"}, {"from": "FIG-058c5c9bbe1a9c12", "to": "FIG-56a052af4bd8b83f", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Multiplizitätsbeschriftung <code>1</code> der Assoziation <code>+startsOnEvent</code> von links unterhalb der Rollenbezeichnung auf die rechte Seite der Pfeilspitze verschoben.</li>\n</ul>"}, {"from": "FIG-56a052af4bd8b83f", "to": "FIG-4a0059011b56e100", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Komposition <code>+arTypedPerInstanceMemory</code> [0..*] von <code>BswInternalBehavior</code> zu <code>VariableDataPrototype</code> entfernt.</li>\n</ul>"}, {"from": "FIG-4a0059011b56e100", "to": "FIG-f3a8bc6e4e85bc52", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Multiplizität der Assoziation <code>+startsOnEvent</code> von <code>BswEvent</code> zu <code>BswModuleEntity</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n</ul>"}, {"from": "FIG-f3a8bc6e4e85bc52", "to": "FIG-8cf8219b80bfc11d", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8cf8219b80bfc11d", "to": "FIG-15b86a8921df3d3c", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
